import {createRequire} from 'node:module';import {readFromGrpc} from './builders.mjs';
const require=createRequire(import.meta.url),{Firestore}=require('@google-cloud/firestore'),sdk=require('@google-cloud/firestore/pipelines');
const normalize=x=>Array.isArray(x)?x.map(normalize):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).map(([k,v])=>[k,k==='integerValue'?String(v):normalize(v)])):x;
// Both paths are generated by the pinned SDK; outcomes remain production observations.
export function subqueryRecipes(){const db=new Firestore({projectId:'demo-local'}),f=sdk.field;const array=sdk.subcollection('probe_children').select(f('value')).toArrayExpression();const scalar=db.pipeline().collectionGroup('probe_children').where(f('parentKey').equal(sdk.variable('parent_key'))).select(f('value')).toScalarExpression();const cases=[['subcollection-array',db.pipeline().collection('subprobe').select(f('key'),array.as('children'))],['correlated-scalar',db.pipeline().collection('subprobe').define(f('key').as('parent_key')).select(f('key'),scalar.as('child'))]];return cases.map(([id,q])=>({id,step:readFromGrpc(id,...normalize(q._toProto().stages))}));}
export function subquerySeed(){return [['subprobe/p1',{key:{stringValue:'A'}}],['subprobe/p2',{key:{stringValue:'B'}}],['subprobe/p1/probe_children/c1',{parentKey:{stringValue:'A'},value:{stringValue:'child-a'}}]];}
